 private static void need(boolean yes,String why){if(!yes)throw new AssertionError("Light GPU: "+why);}
 private static NativeLightEntity.Visual visual(int i,int main,int face,boolean lit){var kind=i==2||i==3||i==9||i==11?NativeLightBlock.Kind.FRAME:i==4||i==5||i==6||i==10?NativeLightBlock.Kind.SLAB:NativeLightBlock.Kind.FULL;var tag=new CompoundTag();tag.putInt("housingTexture",main);tag.putInt("HousingTextureVersion",1);tag.putInt("MainTextureLayout",i%3);var access=new ModernHousingTags(tag);var housing=HousingSettings.read(access,main,false,ModernFinishCatalog::storedChoice,ModernFinishCatalog::validChoice);var catalog=NativeScreenCatalog.INSTANCE;var frames=FrameSettings.read(access,catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);var data=new LightData(i%6,face,-1,15,false,0,0,true,false,0,false);return new NativeLightEntity.Visual(kind,FACINGS[i],i==5||i==6,i==3,new NativeLightSettings(data),housing,frames,PanelGlassSettings.fresh(),PanelPlayback.DEFAULT,lit,15,lit?15:0,0);}
 private static void prepare(){var source=NativePanelPlaybackRenderer.currentBake();need(source!=null,"shared actual material bake");bake=new NativeLightRenderer.Bake(source);scenes=new NativeLightEntity.Visual[12];projections=new NativeLightRenderProjection[12];owners=new BlockPos[12];Integer oak=NativeMaterialRegistry.snapshot().samples().get(net.minecraft.world.level.block.Blocks.OAK_DOOR);need(oak!=null,"actual custom block material");for(int i=0;i<12;i++){int face=i==7?64:i==8||i==9?382:i==10?oak:-1;scenes[i]=visual(i,i==10?oak:9,face,i!=1&&i!=5&&i!=7);owners[i]=new BlockPos(i*2,64,0);projections[i]=i==8?new NativeLightRenderProjection(63,0,0,8,8):i==9?new NativeLightRenderProjection(63,8,8,16,16):NativeLightRenderProjection.SINGLE;}on=visual(7,9,64,true);need(NativePanelPlaybackRenderer.frameRenderType()!=NativePanelPlaybackRenderer.frameRenderType(true),"source Light culling has its own cached layer");}
 private static void align(PoseStack poses,Direction facing){switch(facing){case NORTH->poses.mulPose(Axis.YP.rotationDegrees(180));case WEST->poses.mulPose(Axis.YP.rotationDegrees(90));case EAST->poses.mulPose(Axis.YP.rotationDegrees(-90));case UP->poses.mulPose(Axis.XP.rotationDegrees(90));case DOWN->poses.mulPose(Axis.XP.rotationDegrees(-90));default->{}}}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(done||!"true".equals(System.getenv("VANDOR_LIGHT_RENDER_CHECK"))||!(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(bake==null)prepare();var gui=event.getGuiGraphics();gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();var buffers=mc.renderBuffers().bufferSource();for(int i=0;i<12;i++){int x=10+(i%4)*155,y=8+(i/4)*112;gui.enableScissor(x,y,x+150,y+106);var pose=gui.pose();pose.pushPose();try{pose.translate(x+75,y+53,350);pose.scale(65,-65,65);pose.mulPose(Axis.XP.rotationDegrees(15));pose.mulPose(Axis.YP.rotationDegrees(-25));align(pose,FACINGS[i]);pose.translate(-.5,-.5,-.5);var projection=i==11&&frames<5?new NativeLightRenderProjection(63&~4,0,0,16,16):projections[i];NativeLightRenderer.renderAt(bake,i==7&&frames<5?on:scenes[i],projection,owners[i],pose,buffers,0xF000F0,OverlayTexture.NO_OVERLAY);}finally{pose.popPose();}buffers.endBatch();gui.flush();gui.disableScissor();}if(frames==6)builds=bake.meshBuilds();else if(frames>6)need(bake.meshBuilds()==builds,"stable publication reuses native meshes");capture=++frames>=10;}
 private static final Discard DISCARD=new Discard();
 private static final class Discard implements VertexConsumer {long vertices;public VertexConsumer addVertex(float x,float y,float z){vertices++;return this;}public VertexConsumer setColor(int r,int g,int b,int a){return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
 private static void measure(){var pose=new PoseStack();net.minecraft.client.renderer.MultiBufferSource buffers=type->DISCARD;for(int n=0;n<12000;n++)NativeLightRenderer.renderAt(bake,scenes[0],projections[0],owners[0],pose,buffers,0xF000F0,123);var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(thread),builds=bake.meshBuilds();DISCARD.vertices=0;for(int n=0;n<4096;n++)NativeLightRenderer.renderAt(bake,scenes[0],projections[0],owners[0],pose,buffers,0xF000F0,123);long bytes=meter.getThreadAllocatedBytes(thread)-before;need(bytes==0&&DISCARD.vertices==98304&&bake.meshBuilds()==builds,"warmed native allocation="+bytes+" vertices="+DISCARD.vertices);need(bake.retainedBytes()<=8*1024*1024,"native retained byte limit");System.out.println("[vandorlabs][light-render] cost calls4096 vertices="+DISCARD.vertices+" allocated="+bytes+" newMeshes=0 retainedBytes="+bake.retainedBytes());}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(done||(!capture&&frames!=5))return;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){double scale=mc.getWindow().getGuiScale();int w=(int)(150*scale),h=(int)(106*scale);if(frames==5){negative=new int[2][w*h];for(int n=0;n<2;n++){int i=n==0?7:11,x0=(int)((10+(i%4)*155)*scale),y0=(int)((8+(i/4)*112)*scale);for(int y=0;y<h;y++)for(int x=0;x<w;x++)negative[n][y*w+x]=image.getPixelRGBA(x0+x,y0+y);}measure();return;}done=true;for(int n=0;n<2;n++){int i=n==0?7:11,changed=0,background=0,x0=(int)((10+(i%4)*155)*scale),y0=(int)((8+(i/4)*112)*scale);for(int y=0;y<h;y++)for(int x=0;x<w;x++){if(negative[n][y*w+x]!=image.getPixelRGBA(x0+x,y0+y))changed++;if((negative[n][y*w+x]&0xFFFFFF)==0x302820&&x>w/3&&x<2*w/3&&y>h/3&&y<2*h/3)background++;}need(changed>200,"actual "+(n==0?"Source Off alias":"front visibility")+" negative pixels="+changed);if(n==1)need(background>500,"culled rear housing leaves empty front background="+background);System.out.println("[vandorlabs][light-render] negative="+n+" changed="+changed+" background="+background+" generation="+generation);}for(int i=0;i<12;i++){int ink=0,x0=(int)((10+(i%4)*155)*scale),y0=(int)((8+(i/4)*112)*scale);for(int y=0;y<h;y++)for(int x=0;x<w;x++)if((image.getPixelRGBA(x0+x,y0+y)&0xFFFFFF)!=0x302820)ink++;need(ink>100,"visible actual scene="+i+" ink="+ink);}var path=mc.gameDirectory.toPath().resolve("screenshots/light-native-"+generation+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);}if(generation++==0){bake=null;frames=0;capture=false;done=false;mc.reloadResourcePacks();return;}System.out.println("[vandorlabs][light-render] title PASS scenes12 full/frame/tiny/slab/sixfacings/joinedUV/SourceOff/custommaterial/CULL/frontmask/cache/reload; inactive backend only");mc.stop();}
